mapper.select:
SELECT COUNT(1)
  FROM COURSE_CONSULT CC
 WHERE CC.COURSE_STUDENT_ID = #{_parameter}

mapper.update:
UPDATE COURSE_CONSULT
   SET CAPABILITY_START_LEVEL = #{capabilityStartLevel}
     , CAPABILITY_START_DESC = #{capabilityStartDesc}
     , CAPABILITY_MID_LEVEL = #{capabilityMidLevel}
     , CAPABILITY_MID_DESC = #{capabilityMidDesc}
     , CAPABILITY_END_LEVEL = #{capabilityEndLevel}
     , CAPABILITY_END_DESC = #{capabilityEndDesc}
 WHERE COURSE_STUDENT_ID = #{courseStudentId}

mapper.select:
SELECT CC.OPINION
  FROM COURSE_CONSULT CC
 WHERE CC.COURSE_STUDENT_ID = #{_parameter}

mapper.update:
UPDATE COURSE_CONSULT
   SET OPINION = #{opinion}
 WHERE COURSE_STUDENT_ID = #{courseStudentId}
